"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73469"],{51342(e){e.exports=JSON.parse('{"id":"FIN-1348","slug":"merger-model","term":"Merger Model","also_known_as":[],"difficulty":"Advanced","definition":"A merger model is a financial model that combines the financial statements of an acquiring company and a target company to analyse the effects of an acquisition, especially on the acquirer\'s earnings per share and financial position.","explanation":["Merger models help companies and their advisers decide whether a deal makes financial sense and how to structure it. They project the combined company\'s results under different assumptions about price, financing and synergies.","Key inputs include the purchase price, the mix of cash, debt and shares used to pay, the interest rate on new debt, the share price for any shares issued, expected synergies, transaction fees and purchase price allocation adjustments, such as new amortization of intangible assets.","The main output is usually accretion or dilution: whether the acquirer\'s earnings per share rise or fall after the deal. Models also show pro forma leverage, credit ratios and ownership.","For example, a merger model might show that paying for an acquisition entirely in shares would dilute earnings per share by 3%, while paying with a mix of cash and debt would increase it by 2%, helping the board choose a financing structure. Merger models focus on financial effects, so they should be combined with strategic analysis."],"note":"","total":1725,"prev":{"slug":"merger-and-acquisition","term":"Merger and Acquisition (M&A)"},"next":{"slug":"mezzanine-financing","term":"Mezzanine Financing"}}')}}]);